-- ============================================================================
-- Query Lab dataset: analytics
-- Pulseboard, a SaaS app: signups, daily activity, subscriptions and an A/B test (2025).
--
-- Generated by tools/gen_query_lab_data.py (deterministic; do not edit by hand).
-- Load into the lab Postgres:   psql "postgresql://dsa:dsa@localhost:5544/dsa" -f SQL/lab/datasets/analytics.sql
-- Then:                         SET search_path TO analytics;
-- Tables: users, events, subscriptions, experiment_assignments
-- ============================================================================
DROP SCHEMA IF EXISTS analytics CASCADE;
CREATE SCHEMA analytics;
SET search_path TO analytics;


CREATE TABLE users (
    user_id     INT PRIMARY KEY,
    signup_at   TIMESTAMPTZ NOT NULL,
    channel     TEXT NOT NULL,
    country     TEXT NOT NULL,
    device      TEXT NOT NULL
);
CREATE TABLE events (
    event_id   BIGINT PRIMARY KEY,
    user_id    INT NOT NULL REFERENCES users(user_id),
    event_type TEXT NOT NULL,
    event_at   TIMESTAMPTZ NOT NULL,
    page       TEXT,
    amount     NUMERIC(10,2)
);
CREATE TABLE subscriptions (
    subscription_id INT PRIMARY KEY,
    user_id         INT NOT NULL REFERENCES users(user_id),
    plan            TEXT NOT NULL,
    started_at      TIMESTAMPTZ NOT NULL,
    ended_at        TIMESTAMPTZ,
    mrr             NUMERIC(10,2) NOT NULL
);
CREATE TABLE experiment_assignments (
    user_id     INT NOT NULL REFERENCES users(user_id),
    experiment  TEXT NOT NULL,
    variant     CHAR(1) NOT NULL,
    assigned_at TIMESTAMPTZ NOT NULL,
    converted   BOOLEAN NOT NULL,
    PRIMARY KEY (user_id, experiment)
);


CREATE INDEX ON events (user_id, event_at);
CREATE INDEX ON events (event_type, event_at);
ANALYZE;
